from itertools import combinations


def _route(data, exact, minimum_duration):
    required = data.get("required", [])
    bits = {node: 1 << i for i, node in enumerate(required)}
    full = (1 << len(required)) - 1
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)

    source = data["source"]
    initial_mask = bits.get(source, 0)
    start = data["start"]
    initial_used = 0
    best = {(source, initial_mask, initial_used): start}
    queue = [(start, source, initial_mask, initial_used)]

    while queue:
        arrival, node, mask, used = heapq.heappop(queue)
        if best.get((node, mask, used)) != arrival:
            continue
        if node == data["target"] and mask == full and (not exact or used == data["coupons"]):
            return {"arrival": arrival}

        for edge in graph[node]:
            depart = max(arrival, edge["open"])
            if depart >= edge["close"]:
                continue
            choices = [(edge["duration"], used)]
            if used < data["coupons"]:
                duration = max(minimum_duration,
                               edge["duration"] - edge.get("discount", 0))
                choices.append((duration, used + 1))
            for duration, next_used in choices:
                next_time = depart + duration
                if next_time > data["deadline"]:
                    continue
                next_node = edge["v"]
                next_mask = mask | bits.get(next_node, 0)
                key = (next_node, next_mask, next_used)
                if next_time < best.get(key, float("inf")):
                    best[key] = next_time
                    heapq.heappush(queue, (next_time, next_node, next_mask, next_used))
    return {"arrival": None}


def _build_route(exact, minimum_duration):
    return lambda data: _route(data, exact, minimum_duration)


def _build_ledger():
    def rounded(numerator, denominator, mode):
        quotient, remainder = divmod(numerator, denominator)
        if mode == "half_up" and 2 * remainder >= denominator:
            quotient += 1
        return quotient

    def solve(data):
        cutoff = data.get("cutoff", 10**9)
        chosen = {}
        for position, event in enumerate(data["events"]):
            if event.get("sequence", 0) > cutoff:
                continue
            event_id = event.get("id", "anonymous:" + str(position))
            key = (event.get("revision", 0), position)
            if event_id not in chosen or key > chosen[event_id][0]:
                chosen[event_id] = (key, event)

        balances = dict(data.get("opening", {}))
        mode = data["rounding"]
        for _, event in chosen.values():
            if event.get("void", False):
                continue
            raw = event["price"] * event.get("quantity", 1)
            discount = min(10000, max(0, event.get("discount_bp", 0)))
            net = rounded(raw * (10000 - discount), 10000, mode)
            tax = rounded(net * event.get("tax_bp", 0), 10000, mode)
            total = net + tax
            if event.get("kind") == "refund":
                total = -total
            account = event.get("account", "default")
            currency = event.get("currency", "USD")
            key = account + "|" + currency
            balances[key] = balances.get(key, 0) + total
        return {"balances": balances}
    return solve


def _build_resolver():
    def solve(data):
        packages = data["packages"]
        names = sorted(packages)
        features = set(data.get("features", []))
        blocked = data.get("blocked", {})
        pins = data.get("pins", {})
        roots = data["roots"]
        best_vector = None
        best_versions = None

        def active_deps(row):
            return [dep for dep in row.get("deps", [])
                    if not dep.get("feature") or dep["feature"] in features]

        def acyclic(graph):
            visiting, done = set(), set()

            def visit(name):
                if name in visiting:
                    return False
                if name in done:
                    return True
                visiting.add(name)
                for other in graph.get(name, []):
                    if not visit(other):
                        return False
                visiting.remove(name)
                done.add(name)
                return True

            return all(visit(name) for name in graph)

        def search(chosen, constraints, graph, pending):
            nonlocal best_vector, best_versions
            if not pending:
                if not acyclic(graph):
                    return
                vector = tuple(chosen.get(name, -1) for name in names)
                if best_vector is None or vector < best_vector:
                    best_vector = vector
                    best_versions = dict(chosen)
                return

            name = pending[0]
            rest = pending[1:]
            ranges = constraints.get(name, [])
            if name in chosen:
                version = chosen[name]
                if all(low <= version <= high for low, high in ranges):
                    search(chosen, constraints, graph, rest)
                return

            rows = []
            for row in packages[name]:
                version = row["version"]
                if any(not (low <= version <= high) for low, high in ranges):
                    continue
                if version in blocked.get(name, []):
                    continue
                if name in pins and version != pins[name]:
                    continue
                rows.append(row)

            for row in rows:
                version = row["version"]
                next_chosen = dict(chosen)
                next_chosen[name] = version
                next_constraints = {key: list(value) for key, value in constraints.items()}
                next_graph = {key: list(value) for key, value in graph.items()}
                deps = active_deps(row)
                next_graph[name] = [dep["name"] for dep in deps]
                next_pending = list(rest)
                valid = True
                for dep in deps:
                    dep_name = dep["name"]
                    interval = (dep["min"], dep["max"])
                    next_constraints.setdefault(dep_name, []).append(interval)
                    if dep_name in next_chosen and not interval[0] <= next_chosen[dep_name] <= interval[1]:
                        valid = False
                        break
                    if dep_name not in next_chosen and dep_name not in next_pending:
                        next_pending.append(dep_name)
                if valid:
                    search(next_chosen, next_constraints, next_graph, next_pending)

        constraints = {name: [tuple(bounds)] for name, bounds in roots.items()}
        search({}, constraints, {}, list(roots))
        if best_versions is None:
            return {"error": "unsatisfiable"}
        return {"versions": best_versions}
    return solve


def _build_jobs():
    def solve(data):
        jobs = [job for job in data["jobs"]
                if job["id"] not in data.get("blocked", [])]
        mandatory = set(data.get("mandatory", []))
        if not mandatory.issubset({job["id"] for job in jobs}):
            return {"error": "impossible"}

        k = data["k"]
        quotas = data.get("quotas", {})
        best_value = None
        best_ids = None
        for subset in combinations(jobs, k):
            ids = [job["id"] for job in subset]
            if not mandatory.issubset(ids):
                continue
            counts = {}
            for job in subset:
                counts[job["group"]] = counts.get(job["group"], 0) + 1
            if any(not low <= counts.get(group, 0) <= high
                   for group, (low, high) in quotas.items()):
                continue
            ordered = sorted(subset, key=lambda job: (job["start"], job["end"], job["id"]))
            if any(ordered[i]["end"] > ordered[i + 1]["start"]
                   for i in range(len(ordered) - 1)):
                continue
            value = sum(job["value"] for job in subset)
            selected = tuple(sorted(ids))
            if (best_value is None or value > best_value or
                    (value == best_value and selected > best_ids)):
                best_value, best_ids = value, selected

        if best_value is None:
            return {"error": "impossible"}
        return {"selected": list(best_ids), "value": best_value}
    return solve


